INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('drive forward', '推動前進；積極推進', 'to make something progress or move ahead', '[{"en":"The CEO is committed to driving forward the transformation agenda.","zh-TW":"執行長致力於推動轉型議程前進。"},{"en":"Her energy drives the project forward.","zh-TW":"她的活力推動著專案向前推進。"}]', 'phrasal verb'),
('eliminate from', '從…中排除；淘汰', 'to remove or exclude from a group or process', '[{"en":"Several suppliers were eliminated from the shortlist.","zh-TW":"幾家供應商從最終名單中被排除了。"},{"en":"Eliminate from the options any that do not meet requirements.","zh-TW":"從選項中淘汰任何不符合要求的。"}]', 'phrasal verb'),
('escalate to', '向上呈報；升級到', 'to refer an issue to a higher level of authority', '[{"en":"Unresolved complaints are escalated to the director.","zh-TW":"未解決的投訴會向上呈報給總監。"},{"en":"She escalated the issue to senior management.","zh-TW":"她將問題升級到了高層管理。"}]', 'phrasal verb'),
('extend beyond', '超出；延伸超過', 'to go further in scope or duration than expected', '[{"en":"The timeline may extend beyond the initial estimate.","zh-TW":"時間表可能延伸超過最初的估算。"},{"en":"Impact extended beyond our target market.","zh-TW":"影響超出了我們的目標市場範圍。"}]', 'phrasal verb'),
('fund through', '通過…資助；透過籌資', 'to provide money via a specific source or mechanism', '[{"en":"The project was funded through venture capital.","zh-TW":"該專案通過風險投資資助。"},{"en":"We fund operations through subscription revenue.","zh-TW":"我們通過訂閱收入資助運作。"}]', 'phrasal verb'),
('out of sync', '不同步；不協調', 'not working together smoothly or in the same rhythm', '[{"en":"The two departments are out of sync on priorities.","zh-TW":"兩個部門在優先事項上不同步。"},{"en":"Our pricing is out of sync with market realities.","zh-TW":"我們的定價與市場現實不協調。"}]', 'business idiom'),
('outside the comfort zone', '超出舒適圈；走出舒適圈', 'beyond familiar or safe territory in terms of challenge', '[{"en":"Growth requires stepping outside your comfort zone.","zh-TW":"成長需要走出舒適圈。"},{"en":"She pushed her team outside their comfort zones.","zh-TW":"她推動團隊走出舒適圈。"}]', 'business idiom'),
('pain point analysis', '痛點分析', 'the process of identifying and analyzing specific customer problems', '[{"en":"A thorough pain point analysis guides product development.","zh-TW":"全面的痛點分析指導產品開發。"},{"en":"We used pain point analysis to redesign the user journey.","zh-TW":"我們使用痛點分析重新設計了用戶體驗旅程。"}]', 'business idiom'),
('passing the torch', '交棒；傳承', 'handing over responsibility or leadership to someone else', '[{"en":"The founder passed the torch to the new CEO.","zh-TW":"創辦人把棒子交給了新任執行長。"},{"en":"Passing the torch well ensures continuity.","zh-TW":"順利交棒確保了業務的延續性。"}]', 'business idiom'),
('pay lip service to', '口頭支持；言而無實', 'to express support without taking real action', '[{"en":"Do not just pay lip service to sustainability — act on it.","zh-TW":"不要只是口頭支持永續發展——付諸行動。"},{"en":"Some companies pay lip service to diversity.","zh-TW":"一些公司對多元化只是口頭支持。"}]', 'business idiom'),
('pick up steam', '逐漸加速；蒸蒸日上', 'to gain momentum and speed over time', '[{"en":"Sales are picking up steam after the initial launch.","zh-TW":"初次發布後銷售正在逐漸加速。"},{"en":"The new product line is picking up steam in Europe.","zh-TW":"新產品線在歐洲蒸蒸日上。"}]', 'business idiom'),
('play it safe', '謹慎行事；不冒險', 'to choose the cautious option to avoid risk', '[{"en":"In uncertain times we played it safe with investments.","zh-TW":"在不確定時期我們謹慎行事進行投資。"},{"en":"Playing it safe can mean missing out on big opportunities.","zh-TW":"謹慎行事可能意味著錯失重大機會。"}]', 'business idiom'),
('pound the pavement', '積極開展業務；挨家挨戶推銷', 'to actively work to develop sales or find opportunities', '[{"en":"The sales team pounded the pavement to find new accounts.","zh-TW":"銷售團隊積極開展業務尋找新客戶。"},{"en":"When starting out you have to pound the pavement.","zh-TW":"剛開始時你必須積極地跑業務。"}]', 'business idiom'),
('power play', '權力角力；強勢舉措', 'an attempt to gain power or leverage over others', '[{"en":"The CEO''s announcement was a strategic power play.","zh-TW":"執行長的公告是一個策略性的權力角力行動。"},{"en":"Acquiring the competitor was a power play.","zh-TW":"收購競爭對手是一個強勢舉措。"}]', 'business idiom'),
('price point', '價格點；價位', 'the specific price at which a product is sold to consumers', '[{"en":"We found the right price point to attract mid-market buyers.","zh-TW":"我們找到了吸引中端市場買家的合適價位。"},{"en":"The premium price point limits our customer base.","zh-TW":"高端價位限制了我們的客戶群。"}]', 'business idiom'),
('profit margin', '利潤率', 'the percentage of revenue that becomes profit', '[{"en":"Automation improved our profit margins significantly.","zh-TW":"自動化大幅提高了我們的利潤率。"},{"en":"Rising wages are compressing profit margins.","zh-TW":"不斷上漲的薪資正在壓縮利潤率。"}]', 'business idiom'),
('pull out all the stops', '不遺餘力；全力以赴', 'to do everything possible to achieve a goal', '[{"en":"We pulled out all the stops to win the contract.","zh-TW":"我們不遺餘力地爭取合同。"},{"en":"The event team pulled out all the stops for the gala.","zh-TW":"活動團隊為晚宴全力以赴。"}]', 'business idiom'),
('put something in motion', '啟動；使…開始運作', 'to start a process or plan in action', '[{"en":"The decision has put the restructuring in motion.","zh-TW":"這個決定啟動了重組進程。"},{"en":"She put the new strategy in motion immediately.","zh-TW":"她立即啟動了新策略的執行。"}]', 'business idiom'),
('raise the profile of', '提升…的知名度；提高曝光度', 'to increase awareness or prominence of something', '[{"en":"The campaign raised the profile of the charity.","zh-TW":"這次活動提升了慈善機構的知名度。"},{"en":"Public speaking helped raise her professional profile.","zh-TW":"公開演講有助於提升她的職業知名度。"}]', 'business idiom'),
('reality check', '現實核查；回歸現實', 'an assessment that brings expectations back to reality', '[{"en":"Before overpromising do a reality check on timelines.","zh-TW":"在過度承諾之前對時間表做一個現實核查。"},{"en":"The market data provided a sobering reality check.","zh-TW":"市場數據提供了一個讓人警醒的現實核查。"}]', 'business idiom'),
('results-driven', '以結果為導向', 'focused on achieving measurable outcomes', '[{"en":"Our company culture is results-driven above all.","zh-TW":"我們公司的文化首先是以結果為導向的。"},{"en":"She is a results-driven leader who expects delivery.","zh-TW":"她是一位以結果為導向、期望交付成果的領導者。"}]', 'business idiom'),
('risk appetite', '風險承受能力；風險偏好', 'the level of risk that an organization is willing to accept', '[{"en":"Our risk appetite determines where we invest.","zh-TW":"我們的風險承受能力決定了我們的投資方向。"},{"en":"The board''s risk appetite is conservative.","zh-TW":"董事會的風險偏好是保守的。"}]', 'business idiom'),
('run rings around', '遠超；把…比下去', 'to far outperform a competitor in skills or results', '[{"en":"Our product runs rings around the competition.","zh-TW":"我們的產品遠超競爭對手。"},{"en":"She ran rings around other candidates in the interview.","zh-TW":"她在面試中把其他候選人比下去了。"}]', 'business idiom'),
('sales funnel', '銷售漏斗；客戶轉化流程', 'the stages a customer goes through from awareness to purchase', '[{"en":"We optimized the sales funnel to increase conversion rates.","zh-TW":"我們優化了銷售漏斗以提高轉化率。"},{"en":"Leads enter the top of the sales funnel.","zh-TW":"潛在客戶從銷售漏斗頂端進入。"}]', 'business idiom'),
('scope creep', '範疇蔓延；工作範圍擴大', 'uncontrolled changes or continuous growth in project scope', '[{"en":"Scope creep delayed the project by three months.","zh-TW":"範疇蔓延使專案延遲了三個月。"},{"en":"Define deliverables clearly to prevent scope creep.","zh-TW":"明確定義交付物以防止範疇蔓延。"}]', 'business idiom'),
('turn over a new leaf', '改過自新；重新開始', 'to change behavior or start fresh with better practices', '[{"en":"After the failed quarter the team turned over a new leaf.","zh-TW":"糟糕的季度後團隊改過自新。"},{"en":"The new CEO turned over a new leaf in company culture.","zh-TW":"新任執行長在公司文化上開始了新篇章。"}]', 'expression'),
('under new management', '換了新管理層；新管理下', 'now being operated by different people in charge', '[{"en":"The division is under new management and improving rapidly.","zh-TW":"該部門換了新管理層，正在快速改善。"},{"en":"Under new management the brand regained customer trust.","zh-TW":"在新管理下品牌重新贏得了客戶信任。"}]', 'expression'),
('up for grabs', '待人爭奪；可供競爭', 'available to whoever can get it first', '[{"en":"Market share is up for grabs after the leader exited.","zh-TW":"行業領袖退出後市場份額待人爭奪。"},{"en":"Several senior positions are up for grabs.","zh-TW":"幾個高級職位目前可供競爭。"}]', 'expression'),
('value for money', '物有所值；性價比好', 'good quality relative to the price paid', '[{"en":"Clients expect value for money from every engagement.","zh-TW":"客戶期望每次合作都物有所值。"},{"en":"Our services consistently deliver value for money.","zh-TW":"我們的服務始終提供物有所值的體驗。"}]', 'expression'),
('walking a tightrope', '如履薄冰；要求極度謹慎', 'managing a very difficult situation requiring extreme care', '[{"en":"The CEO is walking a tightrope between cutting costs and retaining talent.","zh-TW":"執行長在削減成本和留住人才之間如履薄冰。"},{"en":"Balancing growth and profitability means walking a tightrope.","zh-TW":"平衡增長與盈利需要如履薄冰。"}]', 'expression'),
('with open arms', '熱誠歡迎；張開雙臂', 'in a very welcoming manner', '[{"en":"The team welcomed the new process with open arms.","zh-TW":"團隊熱情地歡迎了新流程。"},{"en":"Clients received our upgrade proposal with open arms.","zh-TW":"客戶熱誠接受了我們的升級提案。"}]', 'expression'),
('world-class', '世界一流的；頂尖的', 'of the highest international standard or quality', '[{"en":"Our goal is to deliver world-class customer service.","zh-TW":"我們的目標是提供世界一流的客戶服務。"},{"en":"World-class products require world-class processes.","zh-TW":"世界一流的產品需要頂尖的流程支撐。"}]', 'expression'),
('yield results', '產生結果；取得成效', 'to produce a positive outcome or effect', '[{"en":"The new strategy is already yielding results.","zh-TW":"新策略已開始取得成效。"},{"en":"Consistent effort yields results over time.","zh-TW":"持續的努力隨著時間的推移會產生結果。"}]', 'expression'),
('zero in on the target', '精準鎖定目標', 'to focus precisely and clearly on a specific objective', '[{"en":"We zeroed in on the target audience with data.","zh-TW":"我們憑藉數據精準鎖定了目標受眾。"},{"en":"Zero in on the target and do not get distracted.","zh-TW":"精準鎖定目標不要分心。"}]', 'expression'),
('add to the mix', '加入；納入考量', 'to include as an additional factor or element', '[{"en":"Adding flexibility to the mix improved team morale.","zh-TW":"將彈性加入其中提升了團隊士氣。"},{"en":"Social media was added to the marketing mix.","zh-TW":"社交媒體被納入行銷組合中。"}]', 'expression'),
('all things considered', '整體而言；綜合考量之下', 'considering all the relevant factors together', '[{"en":"All things considered the project was a success.","zh-TW":"整體而言這個專案是成功的。"},{"en":"All things considered I recommend we proceed.","zh-TW":"綜合考量之下我建議我們繼續推進。"}]', 'expression'),
('at first glance', '乍看之下；初看', 'when first viewed or considered', '[{"en":"At first glance the costs seem high but they are justified.","zh-TW":"乍看之下成本似乎很高但是是合理的。"},{"en":"At first glance the proposal looks promising.","zh-TW":"初看之下這份提案看起來很有前景。"}]', 'expression'),
('at one''s disposal', '可供某人使用；任某人支配', 'available for one''s use or benefit freely', '[{"en":"We have the best tools at our disposal.","zh-TW":"我們有最好的工具可以使用。"},{"en":"Put all available resources at the team''s disposal.","zh-TW":"將所有可用資源供團隊使用。"}]', 'expression'),
('be caught off guard', '被打個措手不及；出乎意料', 'to be surprised and unprepared for something', '[{"en":"The sudden market shift caught us off guard.","zh-TW":"突然的市場轉變打了我們個措手不及。"},{"en":"She was caught off guard by the client''s question.","zh-TW":"她被客戶的問題問得措手不及。"}]', 'expression'),
('beyond reasonable doubt', '超出合理懷疑；確鑿無疑', 'without any realistic possibility of being wrong', '[{"en":"The data proves beyond reasonable doubt that demand is growing.","zh-TW":"數據確鑿無疑地證明需求正在增長。"},{"en":"Beyond reasonable doubt this strategy is superior.","zh-TW":"無可置疑地這個策略更勝一籌。"}]', 'expression'),
('break ground on', '動工；開始建設', 'to start construction of a new building or initiative', '[{"en":"We broke ground on the new headquarters this spring.","zh-TW":"我們今春開始了新總部的建設。"},{"en":"Breaking ground on the factory marks a major milestone.","zh-TW":"工廠動工標誌著一個重要的里程碑。"}]', 'expression'),
('build a rapport', '建立良好關係；建立信任', 'to develop a harmonious and trusting relationship', '[{"en":"Building a rapport with clients leads to repeat business.","zh-TW":"與客戶建立良好關係帶來了回頭生意。"},{"en":"She has a natural ability to build rapport quickly.","zh-TW":"她有迅速建立信任關係的天賦。"}]', 'expression'),
('carry weight', '有份量；具有影響力', 'to have significant influence or importance', '[{"en":"Her endorsement carries significant weight.","zh-TW":"她的認可具有重大影響力。"},{"en":"That argument carries weight with the board.","zh-TW":"那個論點在董事會中很有份量。"}]', 'expression'),
('in a similar vein', '同樣地；類似地', 'in a related or similar way to what was just mentioned', '[{"en":"In a similar vein we should streamline procurement.","zh-TW":"同樣地我們應該精簡採購流程。"},{"en":"In a similar vein to the previous model this one excels.","zh-TW":"與前一個模型類似這個也表現出色。"}]', 'prepositional phrase'),
('off to a good start', '有個好的開始；開門紅', 'beginning well with positive initial results', '[{"en":"The new partnership is off to a good start.","zh-TW":"新合作關係有個好的開始。"},{"en":"We are off to a good start with over 100 sign-ups.","zh-TW":"我們開門紅獲得了超過100個注冊。"}]', 'prepositional phrase'),
('not to be underestimated', '不可低估', 'important or difficult enough that one should take it seriously', '[{"en":"The competitor is not to be underestimated.","zh-TW":"競爭對手不可低估。"},{"en":"The cost implications are not to be underestimated.","zh-TW":"成本影響不可低估。"}]', 'prepositional phrase'),
('on multiple fronts', '在多個方面；在多條戰線上', 'addressing several areas or challenges simultaneously', '[{"en":"The company is competing on multiple fronts.","zh-TW":"公司在多個方面同時展開競爭。"},{"en":"We are improving on multiple fronts this quarter.","zh-TW":"本季我們在多個方面取得了改進。"}]', 'prepositional phrase'),
('at your fingertips', '唾手可得；隨手可得', 'easily available or accessible when needed', '[{"en":"With this app all client data is at your fingertips.","zh-TW":"有了這個應用程式所有客戶數據唾手可得。"},{"en":"Good systems put decisions at your fingertips.","zh-TW":"好的系統讓決策資訊隨手可得。"}]', 'prepositional phrase'),
('free of charge', '免費；不收費', 'without any cost or payment required', '[{"en":"Shipping is free of charge for orders over 100.","zh-TW":"訂單超過100時免費送貨。"},{"en":"The consultation is provided free of charge.","zh-TW":"諮詢服務免費提供。"}]', 'prepositional phrase'),
('off the shelf', '現成的；不需定制的', 'available immediately without customization', '[{"en":"We chose an off-the-shelf software to reduce cost.","zh-TW":"我們選擇了現成的軟體以降低成本。"},{"en":"Not every solution needs to be custom — off the shelf works.","zh-TW":"並非每個解決方案都需要定制——現成的也可以。"}]', 'prepositional phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('on the cusp of', '在…的臨界點；即將', 'at the point of transitioning to a new state', '[{"en":"We are on the cusp of a major market breakthrough.","zh-TW":"我們即將迎來重大的市場突破。"},{"en":"The company is on the cusp of profitability.","zh-TW":"公司處於盈利的臨界點。"}]', 'prepositional phrase'),
('in accordance to', '按照；遵照', 'following or conforming to a standard or instruction', '[{"en":"All work must proceed in accordance to safety rules.","zh-TW":"所有工作必須按照安全規則進行。"},{"en":"In accordance to the SLA we respond within 24 hours.","zh-TW":"按照服務等級協議我們在24小時內回覆。"}]', 'prepositional phrase'),
('under the umbrella of', '在…的範疇下；屬於', 'falling within the scope or authority of a larger entity', '[{"en":"All subsidiaries operate under the umbrella of the parent company.","zh-TW":"所有子公司在母公司的範疇下運作。"},{"en":"The new initiative falls under the umbrella of corporate social responsibility.","zh-TW":"這項新計劃屬於企業社會責任的範疇。"}]', 'prepositional phrase'),
('within budget', '在預算內；不超支', 'not exceeding the amount of money allocated', '[{"en":"The renovation was completed within budget.","zh-TW":"翻新工程在預算內完成了。"},{"en":"It is essential to stay within budget this quarter.","zh-TW":"本季度保持在預算內至關重要。"}]', 'prepositional phrase'),
('at great lengths', '不厭其煩地；費盡心力地', 'with a great deal of effort or in great detail', '[{"en":"She went to great lengths to explain the risk factors.","zh-TW":"她不厭其煩地解釋了風險因素。"},{"en":"They went to great lengths to ensure client satisfaction.","zh-TW":"他們費盡心力確保客戶滿意度。"}]', 'prepositional phrase'),
('at the end of the day', '歸根究底；最後說來', 'ultimately or when everything is considered', '[{"en":"At the end of the day results speak for themselves.","zh-TW":"歸根究底成果自會說話。"},{"en":"At the end of the day client satisfaction is the priority.","zh-TW":"最後說來客戶滿意度是首要。"}]', 'prepositional phrase'),
('given the circumstances', '鑑於情況；考慮到當時的情形', 'considering the current situation or conditions', '[{"en":"Given the circumstances the team did remarkably well.","zh-TW":"鑑於情況團隊的表現非常出色。"},{"en":"Given the circumstances we chose the conservative option.","zh-TW":"考慮到當時的情形我們選擇了保守選項。"}]', 'prepositional phrase'),
('in many respects', '在許多方面；從多個角度', 'in several ways or from several points of view', '[{"en":"In many respects this year was better than the last.","zh-TW":"在許多方面今年比去年好。"},{"en":"In many respects the two products are similar.","zh-TW":"從多個角度來看這兩款產品是相似的。"}]', 'prepositional phrase'),
('in no uncertain terms', '毫不含糊地；直截了當地', 'in a way that is absolutely clear and unmistakable', '[{"en":"She told them in no uncertain terms to stop the practice.","zh-TW":"她毫不含糊地告訴他們停止這種做法。"},{"en":"The manager explained in no uncertain terms the expectations.","zh-TW":"主管直截了當地說明了期望。"}]', 'prepositional phrase'),
('in relation to', '與…相關；相較於', 'concerning or when compared to something', '[{"en":"Performance is evaluated in relation to set KPIs.","zh-TW":"績效是相較於設定的KPI來評估的。"},{"en":"In relation to competitors our pricing is competitive.","zh-TW":"與競爭對手相比我們的定價具有競爭力。"}]', 'prepositional phrase'),
('in the wake', '在…之後；隨之', 'following as a consequence of an event', '[{"en":"Changes were made in the wake of the data breach.","zh-TW":"數據洩露之後進行了相應的改變。"},{"en":"In the wake of staff departures morale was low.","zh-TW":"員工離職之後士氣低落。"}]', 'prepositional phrase'),
('to this end', '為此；為了這個目的', 'for this purpose; in order to achieve this goal', '[{"en":"To this end we have increased our R&D budget.","zh-TW":"為此我們增加了研發預算。"},{"en":"To this end she organized weekly review sessions.","zh-TW":"為了這個目的她組織了每週的審查會議。"}]', 'prepositional phrase'),
('against the backdrop of', '在…的背景下；以…為背景', 'as context or setting for something that is happening', '[{"en":"Against the backdrop of inflation we revised pricing.","zh-TW":"在通貨膨脹的背景下我們修訂了定價。"},{"en":"Against the backdrop of change we maintained stability.","zh-TW":"以變革為背景我們維持了穩定。"}]', 'prepositional phrase'),
('gather momentum', '積聚動力；加速', 'to build up increasing speed or support', '[{"en":"The campaign is gathering momentum.","zh-TW":"這次活動正在積聚動力。"},{"en":"The project gathered momentum after the first milestone.","zh-TW":"專案在第一個里程碑後加速推進。"}]', 'phrasal verb'),
('hold firm', '堅守立場；保持穩定', 'to remain resolute or stable under pressure', '[{"en":"We held firm on pricing despite pressure.","zh-TW":"我們在壓力下依然堅守定價立場。"},{"en":"The manager held firm on the quality standards.","zh-TW":"主管在品質標準上保持了堅定立場。"}]', 'phrasal verb'),
('link up', '建立聯繫；合作', 'to form a connection or partnership', '[{"en":"We linked up with a regional distributor.","zh-TW":"我們與一家區域分銷商建立了聯繫。"},{"en":"The two startups linked up to create a joint offering.","zh-TW":"兩家新創公司合作推出了聯合服務。"}]', 'phrasal verb'),
('move in on', '插足；進入競爭', 'to begin to compete in someone else''s territory', '[{"en":"Competitors are moving in on our client base.","zh-TW":"競爭對手正在插足我們的客戶群。"},{"en":"We moved in on the premium segment successfully.","zh-TW":"我們成功地進入了高端市場競爭。"}]', 'phrasal verb'),
('originate from', '來自；起源於', 'to begin or develop from a particular place or cause', '[{"en":"The idea originated from a customer complaint.","zh-TW":"這個想法來源於一則客戶投訴。"},{"en":"Delays originate from poor planning.","zh-TW":"延誤源自規劃不足。"}]', 'phrasal verb'),
('pool resources', '整合資源；共享資源', 'to combine resources or skills with others', '[{"en":"The two firms pooled resources for the joint project.","zh-TW":"兩家公司整合資源進行了合作專案。"},{"en":"Pooling resources reduces duplication.","zh-TW":"整合資源減少了重複工作。"}]', 'phrasal verb'),
('put to use', '加以利用；付諸實施', 'to use something for a practical purpose', '[{"en":"She put her analytical skills to use on the project.","zh-TW":"她在專案中加以利用了她的分析技能。"},{"en":"Put this feedback to use to improve the service.","zh-TW":"將這份反饋付諸實施以改善服務。"}]', 'phrasal verb'),
('regroup', '重新集結；重新組織', 'to reorganize after a setback or to plan afresh', '[{"en":"After the failed product launch the team regrouped.","zh-TW":"產品發布失敗後團隊重新集結。"},{"en":"They regrouped and came back with a stronger strategy.","zh-TW":"他們重新組織並帶著更強的策略回來了。"}]', 'phrasal verb'),
('restructure around', '以…為中心重組；圍繞…重構', 'to reorganize with a specific focus or principle', '[{"en":"We restructured around client needs.","zh-TW":"我們以客戶需求為中心重新組織架構。"},{"en":"The team was restructured around three product areas.","zh-TW":"團隊圍繞三個產品領域進行了重組。"}]', 'phrasal verb'),
('sharpen up', '提高；改善；加強', 'to improve performance, skills, or processes', '[{"en":"We need to sharpen up our proposal writing.","zh-TW":"我們需要提高提案撰寫能力。"},{"en":"She sharpened up the team''s presentation skills.","zh-TW":"她提高了團隊的簡報技能。"}]', 'phrasal verb'),
('spell out', '明確說明；逐一解釋', 'to explain something in detail so there is no ambiguity', '[{"en":"Please spell out the deliverables in the contract.","zh-TW":"請在合同中明確說明交付物。"},{"en":"She spelled out the expectations to the new hire.","zh-TW":"她向新員工逐一說明了期望。"}]', 'phrasal verb'),
('spin off', '分拆；衍生出', 'to create a separate company from part of an existing one', '[{"en":"The tech division was spun off as an independent company.","zh-TW":"技術部門被分拆為獨立公司。"},{"en":"The new brand is a spin-off of the parent company.","zh-TW":"新品牌是母公司的衍生品牌。"}]', 'phrasal verb'),
('stand behind', '支持；擔保', 'to confirm support for a decision or product', '[{"en":"We stand behind the quality of every product we sell.","zh-TW":"我們對所售每款產品的品質提供擔保。"},{"en":"She stood behind her team''s recommendation.","zh-TW":"她支持了團隊的建議。"}]', 'phrasal verb'),
('submit for', '提交；送交審批', 'to formally send something for review or approval', '[{"en":"The report was submitted for board review.","zh-TW":"報告已提交給董事會審查。"},{"en":"Please submit for signature by end of day.","zh-TW":"請在今天下班前提交簽字。"}]', 'phrasal verb'),
('supplement with', '以…補充；輔以', 'to add to or enhance something with additional elements', '[{"en":"We supplemented the workshop with online materials.","zh-TW":"我們以線上材料補充了研討會內容。"},{"en":"Supplement the report with charts for clarity.","zh-TW":"用圖表補充報告以增加清晰度。"}]', 'phrasal verb'),
('tackle head-on', '正面應對；迎頭解決', 'to deal with a problem directly and without hesitation', '[{"en":"We tackled the compliance issue head-on.","zh-TW":"我們正面應對了合規問題。"},{"en":"She tackled the conflict head-on and resolved it.","zh-TW":"她迎頭解決了衝突。"}]', 'phrasal verb'),
('tailor to', '針對…量身定制；客製化', 'to adapt something specifically for a particular need', '[{"en":"The training is tailored to each department''s needs.","zh-TW":"培訓是針對每個部門的需求量身定制的。"},{"en":"We tailor our services to each client.","zh-TW":"我們為每位客戶量身定制服務。"}]', 'phrasal verb'),
('test out', '測試；試驗', 'to evaluate whether something works by trying it', '[{"en":"We will test out the new interface with a sample group.","zh-TW":"我們將用一個樣本群體測試新界面。"},{"en":"She tested out the approach in a small pilot.","zh-TW":"她在一個小型試點中測試了這個方法。"}]', 'phrasal verb'),
('threshold on', '達到…門檻；越過界限', 'to cross or set a minimum level or limit', '[{"en":"Set a threshold on expenses before escalating.","zh-TW":"在升級之前為費用設定門檻。"},{"en":"The threshold on losses triggers an automatic review.","zh-TW":"損失門檻觸發自動審查。"}]', 'phrasal verb'),
('train up', '培訓；培養至勝任', 'to give someone the training needed to do a job well', '[{"en":"We trained up the team before the system went live.","zh-TW":"系統上線前我們對團隊進行了培訓。"},{"en":"New hires are trained up within their first month.","zh-TW":"新員工在入職第一個月內接受培訓。"}]', 'phrasal verb'),
('unlock potential', '釋放潛力；激發潛能', 'to reveal or enable hidden capability or value', '[{"en":"Good management unlocks potential in every team member.","zh-TW":"好的管理能夠釋放每個團隊成員的潛力。"},{"en":"AI helps unlock potential in large data sets.","zh-TW":"人工智慧幫助激發大型數據集的潛能。"}]', 'phrasal verb'),
('vary across', '在…之間有所不同；因…而異', 'to differ depending on the context or group', '[{"en":"Pricing strategies vary across different regions.","zh-TW":"定價策略因地區不同而有所差異。"},{"en":"Performance levels vary across team members.","zh-TW":"各團隊成員的績效水準因人而異。"}]', 'phrasal verb'),
('weigh against', '與…比較衡量；考慮利弊', 'to consider the disadvantage of something against its benefit', '[{"en":"Weigh the cost against the long-term benefit.","zh-TW":"把成本與長期效益進行比較衡量。"},{"en":"She weighed the risk against the potential return.","zh-TW":"她將風險與潛在回報進行了比較衡量。"}]', 'phrasal verb'),
('work toward', '努力朝向；致力於', 'to make progress or effort toward achieving a goal', '[{"en":"Both parties are working toward a resolution.","zh-TW":"雙方正在努力朝向解決方案前進。"},{"en":"We are working toward industry certification.","zh-TW":"我們正致力於獲取行業認證。"}]', 'phrasal verb'),
('zero tolerance for', '對…零容忍', 'to completely refuse to accept any instance of something', '[{"en":"We have zero tolerance for discrimination.","zh-TW":"我們對歧視行為零容忍。"},{"en":"Zero tolerance for data breaches was our policy.","zh-TW":"對數據洩露零容忍是我們的政策。"}]', 'phrasal verb'),
('cash flow positive', '現金流為正；現金流盈餘', 'having more cash coming in than going out', '[{"en":"The startup became cash flow positive in year two.","zh-TW":"這家新創公司在第二年實現了現金流為正。"},{"en":"Being cash flow positive is essential for sustainability.","zh-TW":"現金流為正對可持續發展至關重要。"}]', 'business idiom'),
('change agent', '變革推動者；推動改革的人', 'a person who actively works to bring about organizational change', '[{"en":"She acts as a change agent in the digital transformation.","zh-TW":"她在數位轉型中擔任變革推動者。"},{"en":"Change agents are essential for organizational growth.","zh-TW":"變革推動者對組織成長至關重要。"}]', 'business idiom'),
('churn rate', '客戶流失率', 'the rate at which customers stop using a product or service', '[{"en":"A high churn rate signals customer dissatisfaction.","zh-TW":"高客戶流失率表明客戶不滿意。"},{"en":"We focused on support to reduce churn rate.","zh-TW":"我們專注於支援以降低客戶流失率。"}]', 'business idiom'),
('collateral damage', '附帶損失；連帶受害', 'unintended harm caused to people not directly targeted', '[{"en":"The cost cuts caused collateral damage to morale.","zh-TW":"成本削減對士氣造成了附帶損失。"},{"en":"Minimize collateral damage when making major changes.","zh-TW":"進行重大變革時要將附帶損失降到最低。"}]', 'business idiom'),
('content is king', '內容為王', 'valuable content is the most important driver of online success', '[{"en":"In digital marketing content is king.","zh-TW":"在數位行銷中內容為王。"},{"en":"She built her strategy around content is king.","zh-TW":"她圍繞內容為王的原則建立了策略。"}]', 'business idiom'),
('cookie-cutter approach', '千篇一律的方法；模板式做法', 'a standardized approach applied without regard for individual differences', '[{"en":"Avoid a cookie-cutter approach with enterprise clients.","zh-TW":"對企業客戶避免千篇一律的方法。"},{"en":"A cookie-cutter approach rarely works in complex markets.","zh-TW":"在複雜市場中千篇一律的做法很少奏效。"}]', 'business idiom'),
('corporate ladder', '職業晉升階梯；職場等級', 'the hierarchical structure of advancement in a company', '[{"en":"She climbed the corporate ladder through hard work.","zh-TW":"她通過努力工作攀上了職業晉升階梯。"},{"en":"Success on the corporate ladder requires both skill and networking.","zh-TW":"在職場等級上取得成功需要技能和人脈。"}]', 'business idiom'),
('creative destruction', '創造性破壞；破舊立新', 'innovation that destroys old industries while creating new ones', '[{"en":"Creative destruction is reshaping the retail industry.","zh-TW":"創造性破壞正在重塑零售業。"},{"en":"Digital platforms are agents of creative destruction.","zh-TW":"數位平台是創造性破壞的推動者。"}]', 'business idiom'),
('cross-functional team', '跨職能團隊', 'a team with members from different departments or functions', '[{"en":"A cross-functional team was assembled for the launch.","zh-TW":"為了發布活動組建了一個跨職能團隊。"},{"en":"Cross-functional teams drive better innovation.","zh-TW":"跨職能團隊推動更好的創新。"}]', 'business idiom'),
('cross-sell', '交叉銷售；推銷相關產品', 'to sell additional related products to an existing customer', '[{"en":"We cross-sell insurance products to banking clients.","zh-TW":"我們向銀行客戶進行保險產品的交叉銷售。"},{"en":"Cross-selling is a cost-effective growth strategy.","zh-TW":"交叉銷售是具有成本效益的增長策略。"}]', 'business idiom'),
('customer-centric', '以客戶為中心的', 'placing the customer''s needs and experience at the core of decisions', '[{"en":"Our customer-centric approach has driven loyalty.","zh-TW":"我們以客戶為中心的方法推動了忠誠度。"},{"en":"Being customer-centric means listening to feedback.","zh-TW":"以客戶為中心意味著傾聽反饋。"}]', 'business idiom'),
('data-driven decision making', '數據驅動決策', 'using data and analysis as the basis for business decisions', '[{"en":"We moved to data-driven decision making company-wide.","zh-TW":"我們在全公司推行數據驅動決策。"},{"en":"Data-driven decision making reduces guesswork.","zh-TW":"數據驅動決策減少了猜測。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('day one mentality', '第一天心態；保持創業初心', 'maintaining the energy and urgency of a startup even as a large company', '[{"en":"Amazon is famous for its day one mentality.","zh-TW":"亞馬遜以保持第一天心態而聞名。"},{"en":"A day one mentality drives continuous innovation.","zh-TW":"第一天心態推動持續創新。"}]', 'business idiom'),
('deal breaker', '交易破局點；不可接受的條件', 'a condition that would prevent agreement if not met', '[{"en":"The payment terms were a deal breaker for us.","zh-TW":"付款條款對我們來說是交易破局點。"},{"en":"Identify deal breakers early to save time.","zh-TW":"早期識別不可接受的條件以節省時間。"}]', 'business idiom'),
('decision tree', '決策樹；決策圖', 'a diagram showing choices and their consequences to aid decisions', '[{"en":"We used a decision tree to map out options.","zh-TW":"我們使用決策樹來映射選項。"},{"en":"A decision tree helps visualize complex choices.","zh-TW":"決策樹有助於視覺化複雜的選擇。"}]', 'business idiom'),
('deep pockets', '財力雄厚；資金充裕', 'having a lot of money available to spend', '[{"en":"Entering that market requires deep pockets.","zh-TW":"進入那個市場需要財力雄厚。"},{"en":"Competitors with deep pockets can outspend us.","zh-TW":"財力雄厚的競爭對手在支出上可以超過我們。"}]', 'business idiom'),
('deliverable', '交付物；成果物', 'a product or result that must be produced and delivered', '[{"en":"Each phase has specific deliverables and deadlines.","zh-TW":"每個階段都有特定的交付物和截止日期。"},{"en":"Review deliverables with the client before starting.","zh-TW":"在開始前與客戶審查交付物。"}]', 'business idiom'),
('demand generation', '需求創造；需求拉動', 'marketing activities aimed at generating awareness and demand', '[{"en":"Demand generation is the foundation of our growth strategy.","zh-TW":"需求創造是我們增長策略的基礎。"},{"en":"Content marketing drives demand generation effectively.","zh-TW":"內容行銷有效地推動需求創造。"}]', 'business idiom'),
('differentiated offering', '差異化產品；差異化服務', 'a product or service that stands out from competitors', '[{"en":"Our differentiated offering is based on superior support.","zh-TW":"我們的差異化服務基於卓越的支援。"},{"en":"A differentiated offering is key to winning clients.","zh-TW":"差異化產品是贏得客戶的關鍵。"}]', 'business idiom'),
('digital footprint', '數位足跡；網路影響力', 'the trail of data left by an organization''s online activities', '[{"en":"Building a digital footprint helps attract talent.","zh-TW":"建立數位足跡有助於吸引人才。"},{"en":"Their digital footprint grew after the rebranding.","zh-TW":"品牌重塑後他們的數位影響力增長了。"}]', 'business idiom'),
('digital transformation', '數位轉型', 'integrating digital technology into all areas of a business', '[{"en":"Digital transformation is essential for modern businesses.","zh-TW":"數位轉型對現代企業至關重要。"},{"en":"She led the digital transformation of the entire division.","zh-TW":"她主導了整個部門的數位轉型。"}]', 'business idiom'),
('disruptive technology', '顛覆性技術', 'technology that fundamentally changes an industry or market', '[{"en":"Blockchain is a disruptive technology in finance.","zh-TW":"區塊鏈是金融業的顛覆性技術。"},{"en":"Disruptive technology creates both risk and opportunity.","zh-TW":"顛覆性技術既帶來風險也帶來機遇。"}]', 'business idiom'),
('due diligence process', '盡職調查流程', 'the systematic procedure for evaluating a business before a deal', '[{"en":"The due diligence process uncovered significant liabilities.","zh-TW":"盡職調查流程揭示了重大負債。"},{"en":"A rigorous due diligence process protects investors.","zh-TW":"嚴格的盡職調查流程保護投資者。"}]', 'business idiom'),
('economies of scope', '範疇經濟；多元化成本優勢', 'cost advantages from producing multiple products together', '[{"en":"Economies of scope allow us to serve multiple segments efficiently.","zh-TW":"範疇經濟使我們能夠高效服務多個市場細分。"},{"en":"The merger created economies of scope across divisions.","zh-TW":"合併在各部門創造了範疇經濟效益。"}]', 'business idiom'),
('end game', '最終目標；最終結局', 'the final stage or ultimate goal of a strategy', '[{"en":"What is the end game of this acquisition?","zh-TW":"這次收購的最終目標是什麼？"},{"en":"Define the end game before committing resources.","zh-TW":"在投入資源前確定最終目標。"}]', 'business idiom'),
('act on', '依據…採取行動；落實', 'to take action based on information or advice', '[{"en":"We acted on the consultant''s recommendations immediately.","zh-TW":"我們立即依據顧問的建議採取了行動。"},{"en":"They failed to act on the early warning signs.","zh-TW":"他們未能對早期預警信號採取行動。"}]', 'phrasal verb'),
('add up', '累計；合計；說得通', 'to total a sum; to make sense logically', '[{"en":"The expenses add up to more than we budgeted.","zh-TW":"費用累計超過了我們的預算。"},{"en":"His explanation just doesn''t add up.","zh-TW":"他的解釋就是說不通。"}]', 'phrasal verb'),
('adhere to', '遵守；堅持；遵循', 'to follow rules, plans, or principles strictly', '[{"en":"All teams must adhere to the new compliance policy.","zh-TW":"所有團隊必須遵守新的合規政策。"},{"en":"We adhere to international quality standards.","zh-TW":"我們遵循國際品質標準。"}]', 'phrasal verb'),
('align with', '與…一致；符合', 'to be in agreement or consistent with something', '[{"en":"Our proposal aligns with the company''s long-term strategy.","zh-TW":"我們的提案與公司的長期策略一致。"},{"en":"Ensure your KPIs align with organizational objectives.","zh-TW":"確保你的關鍵績效指標與組織目標一致。"}]', 'phrasal verb'),
('answer to', '向…負責；向…匯報', 'to be accountable to someone; to report to a superior', '[{"en":"The project manager answers to the VP of Operations.","zh-TW":"專案經理向營運副總裁匯報。"},{"en":"Every team member answers to their direct supervisor.","zh-TW":"每位團隊成員都向其直屬上司負責。"}]', 'phrasal verb'),
('apply for', '申請', 'to formally request something such as a job or funding', '[{"en":"She applied for the senior analyst position last week.","zh-TW":"她上週申請了高級分析師職位。"},{"en":"We are applying for a government innovation grant.","zh-TW":"我們正在申請政府創新補助。"}]', 'phrasal verb'),
('ask for', '要求；請求', 'to request something from someone', '[{"en":"Don''t hesitate to ask for clarification during meetings.","zh-TW":"在會議中不要猶豫，請求澄清。"},{"en":"We asked for an extension on the deadline.","zh-TW":"我們請求延長截止日期。"}]', 'phrasal verb'),
('back down', '退讓；讓步；撤回立場', 'to withdraw from a claim or position under pressure', '[{"en":"He refused to back down from his pricing proposal.","zh-TW":"他拒絕從定價提案上退讓。"},{"en":"She backed down when presented with the data.","zh-TW":"面對數據後她撤回了立場。"}]', 'phrasal verb'),
('bank on', '依賴；指望；寄望於', 'to rely heavily on something happening', '[{"en":"Don''t bank on landing that account this quarter.","zh-TW":"這個季度不要太指望拿下那個客戶。"},{"en":"We banked on the market recovering quickly.","zh-TW":"我們寄望於市場迅速復甦。"}]', 'phrasal verb'),
('bear out', '證實；支持（說法）', 'to confirm or support the truth of something', '[{"en":"The sales figures bear out our earlier forecast.","zh-TW":"銷售數字證實了我們早前的預測。"},{"en":"The research bears out the hypothesis.","zh-TW":"研究支持了這個假說。"}]', 'phrasal verb'),
('block out', '預留時間；遮蔽；屏蔽', 'to reserve time in a schedule; to prevent something from entering', '[{"en":"Block out two hours on Friday for strategic planning.","zh-TW":"在週五預留兩個小時用於策略規劃。"},{"en":"Use noise-canceling headphones to block out distractions.","zh-TW":"使用降噪耳機來屏蔽干擾。"}]', 'phrasal verb'),
('bottom out', '跌到谷底；達到最低點', 'to reach the lowest point before recovering', '[{"en":"Sales bottomed out in Q2 before recovering.","zh-TW":"銷售在第二季跌到谷底後才開始回升。"},{"en":"The stock price bottomed out at five dollars.","zh-TW":"股價跌至谷底為五美元。"}]', 'phrasal verb'),
('burn through', '燒錢；快速耗盡（資源）', 'to use up money or resources rapidly', '[{"en":"The startup burned through its funding in six months.","zh-TW":"這家新創公司在六個月內燒光了資金。"},{"en":"Be careful not to burn through your goodwill too quickly.","zh-TW":"注意不要過快消耗你積累的商譽。"}]', 'phrasal verb'),
('buy in', '認同；取得支持；入股', 'to agree with and support an idea; to purchase a stake', '[{"en":"We need senior leadership to buy in to the new strategy.","zh-TW":"我們需要高層管理人員認同新策略。"},{"en":"She bought in to the startup early and profited greatly.","zh-TW":"她早期入股了這家新創公司並獲得了豐厚回報。"}]', 'phrasal verb'),
('buy out', '收購；買斷；買走（股份）', 'to purchase all shares or interests from a partner or owner', '[{"en":"The firm bought out its minority partner last year.","zh-TW":"這家公司去年買斷了少數股東的股份。"},{"en":"They plan to buy out the founders after the IPO.","zh-TW":"他們計劃在首次公開發行後買斷創始人股份。"}]', 'phrasal verb'),
('carry forward', '結轉；延續；繼承', 'to transfer a balance or principle to the next period or context', '[{"en":"Unused vacation days can be carried forward to next year.","zh-TW":"未使用的假期可以結轉到明年。"},{"en":"Carry forward the lessons from this project.","zh-TW":"延續這個專案的經驗教訓。"}]', 'phrasal verb'),
('cash in', '兌現；從…獲益；套現', 'to convert assets into money; to take advantage of an opportunity', '[{"en":"He cashed in his stock options before the dip.","zh-TW":"他在股價下跌前兌現了股票期權。"},{"en":"The company cashed in on the e-commerce boom.","zh-TW":"該公司從電子商務熱潮中獲益。"}]', 'phrasal verb'),
('chase down', '追查；追蹤；催要', 'to follow up persistently to obtain something or find information', '[{"en":"I had to chase down three clients for overdue invoices.","zh-TW":"我不得不催促三位客戶支付逾期發票。"},{"en":"She chased down the missing data before the report deadline.","zh-TW":"她在報告截止前追查到了遺失的數據。"}]', 'phrasal verb'),
('a bitter pill to swallow', '難以接受的事；苦澀的教訓', 'something unpleasant that must be accepted', '[{"en":"Losing that contract was a bitter pill to swallow.","zh-TW":"失去那份合約是一件難以接受的事。"},{"en":"The pay cut was a bitter pill to swallow for everyone.","zh-TW":"減薪對所有人來說都是難以接受的事。"}]', 'expression'),
('a catch-22 situation', '兩難困境；無論怎樣都有問題的局面', 'a paradoxical situation where no good solution exists', '[{"en":"It''s a catch-22 situation — we need experience to get the job but need the job for experience.","zh-TW":"這是兩難困境——我們需要經驗才能獲得工作，但需要工作來獲取經驗。"},{"en":"The budget freeze created a catch-22 situation for expansion.","zh-TW":"預算凍結為擴張創造了兩難困境。"}]', 'expression'),
('a step in the right direction', '朝正確方向邁出的一步', 'progress that moves toward a goal, even if it''s small', '[{"en":"The new policy is a step in the right direction.","zh-TW":"新政策是朝正確方向邁出的一步。"},{"en":"Approving the pilot is a step in the right direction.","zh-TW":"批准試點項目是朝正確方向邁出的一步。"}]', 'expression'),
('all hands on deck', '全體出動；全力以赴', 'everyone is needed to help with an urgent situation', '[{"en":"It''s all hands on deck for the product launch.","zh-TW":"為了產品發布大家全體出動。"},{"en":"All hands on deck when the system goes down.","zh-TW":"系統崩潰時需要全員全力以赴。"}]', 'expression'),
('back to basics', '回歸基本；返璞歸真', 'returning to simple, fundamental principles', '[{"en":"After several failed initiatives we went back to basics.","zh-TW":"幾次失敗的計劃後我們回歸了基本原則。"},{"en":"The new manager advocated going back to basics.","zh-TW":"新任經理倡導回歸基本。"}]', 'expression'),
('bear the brunt', '承受主要的衝擊；首當其衝', 'to suffer the worst part of something unpleasant', '[{"en":"The front-line staff bore the brunt of customer complaints.","zh-TW":"前線員工首當其衝承受了客戶投訴。"},{"en":"The sales team bore the brunt of the market downturn.","zh-TW":"銷售團隊承受了市場下滑的主要衝擊。"}]', 'expression'),
('burning platform', '燃燒的平台；迫切的危機', 'a situation so urgent that immediate action is required', '[{"en":"Leadership used the data breach as a burning platform for IT reform.","zh-TW":"領導層利用數據洩露事件作為推動IT改革的迫切危機。"},{"en":"A burning platform can motivate rapid organizational change.","zh-TW":"迫切的危機能夠推動快速的組織變革。"}]', 'expression'),
('by the same token', '同樣地；基於同樣的理由', 'in the same way or for the same reason', '[{"en":"We reward hard work; by the same token we address underperformance.","zh-TW":"我們獎勵努力工作；同樣地我們也處理表現不佳的問題。"},{"en":"By the same token if targets rise bonuses also rise.","zh-TW":"基於同樣的理由，如果目標提高獎金也會提高。"}]', 'expression'),
('call a spade a spade', '直言不諱；實話實說', 'to speak plainly and honestly, even if uncomfortable', '[{"en":"The manager called a spade a spade about the project''s failures.","zh-TW":"經理對專案的失敗直言不諱。"},{"en":"In performance reviews we call a spade a spade.","zh-TW":"在績效審查中我們實話實說。"}]', 'expression'),
('change horses midstream', '中途換人；中途改變計劃', 'to change strategy or leadership in the middle of a project', '[{"en":"Changing horses midstream disrupted the project timeline.","zh-TW":"中途換人打亂了專案時間表。"},{"en":"It''s risky to change horses midstream in a product launch.","zh-TW":"在產品發布中途改變計劃是有風險的。"}]', 'expression'),
('clear the decks', '清理工作；清除障礙；準備就緒', 'to remove obstacles or distractions to prepare for action', '[{"en":"Clear the decks before the new project kicks off.","zh-TW":"在新專案啟動前清理工作。"},{"en":"We cleared the decks of low-priority tasks to focus on the launch.","zh-TW":"我們清除了低優先級任務以專注於發布。"}]', 'expression'),
('climb on the bandwagon', '跟風；隨波逐流', 'to join a trend or popular movement, often without deep conviction', '[{"en":"Every firm seems to be climbing on the AI bandwagon.","zh-TW":"每家公司似乎都在跟風人工智慧浪潮。"},{"en":"Don''t just climb on the bandwagon — ensure it fits your strategy.","zh-TW":"不要只是跟風——確保它符合你的策略。"}]', 'expression'),
('come up short', '未達標；不足；差一點', 'to fail to meet a goal or expectation', '[{"en":"We came up short of our revenue target this quarter.","zh-TW":"本季我們未達到收入目標。"},{"en":"The proposal came up short on key details.","zh-TW":"提案在關鍵細節上有所不足。"}]', 'expression'),
('connect the dots', '串連線索；理清脈絡', 'to find the relationship between separate pieces of information', '[{"en":"The analyst connected the dots to uncover the fraud.","zh-TW":"分析師串連了線索揭露了詐騙行為。"},{"en":"Connect the dots between customer feedback and product issues.","zh-TW":"理清客戶反饋與產品問題之間的脈絡。"}]', 'expression'),
('cost an arm and a leg', '花費昂貴；所費不貲', 'to be very expensive', '[{"en":"Hiring top talent in this city costs an arm and a leg.","zh-TW":"在這座城市招募頂尖人才所費不貲。"},{"en":"The renovation is going to cost an arm and a leg.","zh-TW":"這次翻新將會花費昂貴。"}]', 'expression'),
('count one''s chickens before they hatch', '過早樂觀；打如意算盤', 'to make plans based on something that hasn''t happened yet', '[{"en":"Don''t count your chickens before they hatch — the deal isn''t signed yet.","zh-TW":"別打如意算盤——合約還沒簽。"},{"en":"Forecasting huge profits before launch is counting chickens.","zh-TW":"在發布前預測巨大利潤是打如意算盤。"}]', 'expression'),
('at arm''s length', '保持距離；客觀獨立（的關係）', 'maintaining an independent, non-personal relationship', '[{"en":"Keep contractors at arm''s length during the bid process.","zh-TW":"在投標過程中與承包商保持適當距離。"},{"en":"The board is kept at arm''s length from daily operations.","zh-TW":"董事會與日常業務保持客觀獨立的距離。"}]', 'prepositional phrase'),
('at breakneck speed', '以飛快的速度；極速地', 'at an extremely fast and possibly dangerous pace', '[{"en":"The startup expanded at breakneck speed last year.","zh-TW":"這家新創公司去年以飛快的速度擴張。"},{"en":"Technology is advancing at breakneck speed.","zh-TW":"技術正在以極快的速度進步。"}]', 'prepositional phrase'),
('at the helm', '掌舵；擔任領導職位', 'in charge or in a leadership position', '[{"en":"She has been at the helm of the company for five years.","zh-TW":"她擔任公司領導職位已有五年。"},{"en":"With an experienced CEO at the helm growth accelerated.","zh-TW":"在經驗豐富的執行長掌舵下，成長加速了。"}]', 'prepositional phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('below the radar', '未引起注意；低調', 'not attracting attention or notice', '[{"en":"The competitor has been operating below the radar.","zh-TW":"這個競爭對手一直在低調運營。"},{"en":"We kept the new product below the radar until launch.","zh-TW":"我們在發布前讓新產品保持低調。"}]', 'prepositional phrase'),
('beyond one''s control', '超出控制範圍；無法控制的', 'outside the ability to influence or manage', '[{"en":"The delay is beyond our control due to weather.","zh-TW":"由於天氣原因，延誤超出了我們的控制範圍。"},{"en":"Some risks are beyond any team''s control.","zh-TW":"有些風險超出任何團隊的控制範圍。"}]', 'prepositional phrase'),
('by default', '預設情況下；在無其他選項時', 'because no other option was chosen; as a fallback', '[{"en":"We won the contract by default when the rival withdrew.","zh-TW":"競爭對手退出後，我們預設獲得了合約。"},{"en":"By default the system logs all transactions.","zh-TW":"預設情況下系統記錄所有交易。"}]', 'prepositional phrase'),
('contrary to expectations', '與預期相反；出乎意料地', 'opposite to what was expected or predicted', '[{"en":"Contrary to expectations sales rose in Q4.","zh-TW":"與預期相反，第四季銷售額上升了。"},{"en":"Contrary to expectations the product found a new market.","zh-TW":"出乎意料地，產品找到了新市場。"}]', 'prepositional phrase'),
('down to the wire', '到最後一刻；直到最後關頭', 'continuing until the very last moment', '[{"en":"Negotiations went down to the wire before an agreement was reached.","zh-TW":"談判持續到最後一刻才達成協議。"},{"en":"The project was completed down to the wire.","zh-TW":"專案一直到最後關頭才完成。"}]', 'prepositional phrase'),
('for good measure', '附帶地；順便再加上', 'in addition to what is needed, as an extra precaution or bonus', '[{"en":"He added a year of warranty for good measure.","zh-TW":"他附帶地增加了一年保固。"},{"en":"Send the summary and attach the original report for good measure.","zh-TW":"傳送摘要並附上原始報告以作補充。"}]', 'prepositional phrase'),
('for the record', '為了存檔；鄭重聲明', 'stated formally so it is noted or documented', '[{"en":"For the record I objected to this proposal from the start.","zh-TW":"鄭重聲明，我從一開始就反對這個提案。"},{"en":"Let me note for the record that the budget was approved.","zh-TW":"為了存檔，我要記錄預算已獲批准。"}]', 'prepositional phrase'),
('close out', '結清；結束；平倉', 'to finalize or conclude; to clear remaining inventory or positions', '[{"en":"We need to close out the project before year end.","zh-TW":"我們需要在年底前結束這個專案。"},{"en":"Close out the inventory at a discount to make space.","zh-TW":"以折扣清倉以騰出空間。"}]', 'phrasal verb'),
('come apart', '崩潰；分裂；瓦解', 'to fall apart or break down; to lose cohesion', '[{"en":"The plan came apart when the key vendor dropped out.","zh-TW":"當關鍵供應商退出後計劃崩潰了。"},{"en":"The team came apart under the pressure of tight deadlines.","zh-TW":"在緊迫截止日期的壓力下團隊開始瓦解。"}]', 'phrasal verb'),
('come around', '轉變立場；接受新想法', 'to change one''s opinion and agree with someone', '[{"en":"He eventually came around to supporting the new policy.","zh-TW":"他最終轉變立場，支持了新政策。"},{"en":"The board came around to the restructuring proposal.","zh-TW":"董事會最終接受了重組提案。"}]', 'phrasal verb'),
('cut across', '跨越；橫切；涉及多個領域', 'to affect or involve multiple categories or groups', '[{"en":"This policy cuts across all departments.","zh-TW":"這項政策涉及所有部門。"},{"en":"The initiative cuts across traditional industry boundaries.","zh-TW":"這項計劃跨越了傳統行業界限。"}]', 'phrasal verb'),
('dig into', '深入探討；仔細研究', 'to examine or explore something thoroughly', '[{"en":"Let''s dig into the Q3 numbers more carefully.","zh-TW":"讓我們更仔細地深入研究第三季的數字。"},{"en":"She dug into the customer complaints to find the root cause.","zh-TW":"她深入探討了客戶投訴以找到根本原因。"}]', 'phrasal verb'),
('double down', '加倍努力；加大投入', 'to increase commitment to a strategy or action', '[{"en":"We decided to double down on our core market.","zh-TW":"我們決定加倍投入核心市場。"},{"en":"Double down on what''s working before exploring new channels.","zh-TW":"在探索新渠道之前加倍專注於有效的方法。"}]', 'phrasal verb'),
('fire up', '激勵；激發熱情；啟動', 'to energize or motivate someone; to start a system', '[{"en":"The CEO''s speech fired up the sales team.","zh-TW":"執行長的演講激勵了銷售團隊。"},{"en":"Fire up the new CRM system before the client meeting.","zh-TW":"在客戶會議前啟動新的CRM系統。"}]', 'phrasal verb'),
('front-load', '前置（費用或工作量）；提前集中', 'to place a larger portion of work, cost, or effort at the beginning', '[{"en":"The project was front-loaded with heavy testing phases.","zh-TW":"這個專案在前期集中了大量測試階段。"},{"en":"Front-load training to avoid costly mistakes later.","zh-TW":"提前集中培訓以避免後期代價高昂的錯誤。"}]', 'phrasal verb'),
('gear up', '準備就緒；備戰；積極準備', 'to prepare or get ready for an activity or challenge', '[{"en":"We are gearing up for the busy holiday season.","zh-TW":"我們正在為繁忙的假日旺季準備就緒。"},{"en":"The factory geared up production ahead of peak demand.","zh-TW":"工廠在需求高峰前積極準備提升產量。"}]', 'phrasal verb'),
('get ahead', '取得進展；先行一步；超越', 'to make progress; to advance ahead of others', '[{"en":"To get ahead we must invest in talent development.","zh-TW":"要取得進展，我們必須投資人才發展。"},{"en":"Get ahead of the regulatory changes by acting now.","zh-TW":"現在採取行動，以便在監管變化前先行一步。"}]', 'phrasal verb'),
('deliver on the promise', '兌現承諾；落實諾言', 'to follow through on what was promised', '[{"en":"The product must deliver on the promise made in the ads.","zh-TW":"產品必須兌現廣告中所做的承諾。"},{"en":"Deliver on the promise or risk losing trust.","zh-TW":"兌現承諾否則會失去信任。"}]', 'expression'),
('dog-eat-dog', '弱肉強食；激烈競爭的', 'highly competitive with little concern for others'' welfare', '[{"en":"It''s a dog-eat-dog market out there.","zh-TW":"外面是個弱肉強食的市場。"},{"en":"In a dog-eat-dog industry differentiation is crucial.","zh-TW":"在激烈競爭的行業中差異化至關重要。"}]', 'expression'),
('don''t burn bridges', '不要毀掉人脈；不要斷了退路', 'avoid damaging relationships that may be useful in the future', '[{"en":"Don''t burn bridges when you leave a company.","zh-TW":"離開公司時不要毀掉人脈。"},{"en":"Even in tough negotiations don''t burn bridges.","zh-TW":"即使在艱難談判中也不要斷了退路。"}]', 'expression'),
('elephant in the room', '眾所周知卻被刻意迴避的問題', 'an obvious problem that no one wants to discuss', '[{"en":"Let''s address the elephant in the room — we missed our targets.","zh-TW":"讓我們面對眾所周知的問題——我們沒有達到目標。"},{"en":"The budget shortfall was the elephant in the room.","zh-TW":"預算短缺是眾人迴避的問題。"}]', 'expression'),
('give the green light', '批准；開綠燈', 'to give approval to proceed with something', '[{"en":"Management gave the green light to the expansion.","zh-TW":"管理層批准了擴張計劃。"},{"en":"The committee gave the green light for the new policy.","zh-TW":"委員會批准了新政策。"}]', 'expression'),
('in the driver''s seat', '掌控局面；主導地位', 'in a position of control or authority', '[{"en":"Our brand is in the driver''s seat in the premium segment.","zh-TW":"我們的品牌在高端市場佔據主導地位。"},{"en":"With more data we put customers in the driver''s seat.","zh-TW":"有了更多數據，我們讓客戶掌控局面。"}]', 'expression'),
('keep one''s eye on the ball', '專注目標；保持專注', 'to remain focused on the main objective', '[{"en":"Keep your eye on the ball and don''t get distracted by secondary issues.","zh-TW":"保持專注，不要被次要問題分心。"},{"en":"Good managers keep their eye on the ball even under pressure.","zh-TW":"優秀的經理即使在壓力下也能保持目標專注。"}]', 'expression'),
('lay one''s cards on the table', '攤牌；坦誠相告', 'to be open and honest about one''s intentions or information', '[{"en":"In the final negotiation we laid our cards on the table.","zh-TW":"在最後談判中我們攤牌了。"},{"en":"Lay your cards on the table to build trust.","zh-TW":"坦誠相告以建立信任。"}]', 'expression'),
('outside the box', '突破常規；有創意地', 'thinking in a creative or unconventional way', '[{"en":"We need to think outside the box to solve this issue.","zh-TW":"我們需要突破常規來解決這個問題。"},{"en":"Thinking outside the box led to a breakthrough product.","zh-TW":"突破常規思維帶來了突破性產品。"}]', 'expression'),
('put one''s best foot forward', '全力以赴；展現最佳狀態', 'to make the best possible impression or effort', '[{"en":"Put your best foot forward in the client pitch.","zh-TW":"在客戶推介中全力以赴展現最佳狀態。"},{"en":"We put our best foot forward during the investor meeting.","zh-TW":"我們在投資者會議中展現了最佳狀態。"}]', 'expression'),
('seal the deal', '完成交易；成交', 'to finalize an agreement or close a sale', '[{"en":"The free pilot project helped seal the deal.","zh-TW":"免費試點項目幫助促成了交易。"},{"en":"A personal visit from the CEO sealed the deal.","zh-TW":"執行長的親自拜訪完成了這筆交易。"}]', 'expression'),
('take it to the next level', '更上一層樓；提升到更高境界', 'to improve or advance something to a higher standard', '[{"en":"We plan to take our customer experience to the next level.","zh-TW":"我們計劃將客戶體驗更上一層樓。"},{"en":"The new investment will take the platform to the next level.","zh-TW":"新投資將使平台提升到更高境界。"}]', 'expression'),
('the devil is in the details', '細節決定成敗；魔鬼藏在細節裡', 'small, often overlooked details can cause serious problems', '[{"en":"The devil is in the details of the contract terms.","zh-TW":"合約條款的細節決定成敗。"},{"en":"Review every clause — the devil is in the details.","zh-TW":"審查每個條款——魔鬼藏在細節裡。"}]', 'expression'),
('think on one''s feet', '即興應對；臨機應變', 'to make quick decisions without time to prepare', '[{"en":"Good salespeople can think on their feet during tough questions.","zh-TW":"優秀的銷售人員在面對棘手問題時能夠臨機應變。"},{"en":"She thinks on her feet brilliantly under pressure.","zh-TW":"她在壓力下即興應對的能力非常出色。"}]', 'expression'),
('turn the tables', '扭轉局勢；反敗為勝', 'to reverse a situation in your favor', '[{"en":"The competitor turned the tables with a surprise price cut.","zh-TW":"競爭對手以突然降價扭轉了局勢。"},{"en":"Innovation allowed us to turn the tables on industry rivals.","zh-TW":"創新使我們能夠反敗為勝對抗行業競爭者。"}]', 'expression'),
('on par with', '與…相當；旗鼓相當', 'equal to or at the same level as', '[{"en":"Our service quality is on par with industry leaders.","zh-TW":"我們的服務品質與行業領先者相當。"},{"en":"Salaries must be on par with market rates.","zh-TW":"薪資必須與市場水準相當。"}]', 'prepositional phrase'),
('on the brink of', '瀕臨；即將到達', 'very close to a significant event, often negative', '[{"en":"The company was on the brink of bankruptcy when rescued.","zh-TW":"公司在被救助時瀕臨破產。"},{"en":"We are on the brink of a major technology breakthrough.","zh-TW":"我們即將達到一個重大技術突破。"}]', 'prepositional phrase'),
('out of proportion', '不成比例；誇大其詞', 'not matching the scale or importance of something', '[{"en":"The media coverage was out of proportion to the actual issue.","zh-TW":"媒體報導相對於實際問題不成比例。"},{"en":"Don''t let a small setback grow out of proportion.","zh-TW":"不要讓小挫折被誇大其詞。"}]', 'prepositional phrase'),
('without prejudice', '在不損害權益的情況下；保留法律權益', 'without affecting one''s legal rights; used in negotiations to protect positions', '[{"en":"The settlement was discussed without prejudice.","zh-TW":"和解在保留法律權益的情況下進行了討論。"},{"en":"Mark offers as without prejudice in sensitive negotiations.","zh-TW":"在敏感談判中將提議標注為保留法律權益。"}]', 'prepositional phrase'),
('work in tandem', '協同合作；齊頭並進', 'to work together closely or simultaneously', '[{"en":"Sales and marketing work in tandem to close deals.","zh-TW":"銷售和行銷協同合作以達成交易。"},{"en":"The two systems work in tandem to process orders.","zh-TW":"這兩個系統齊頭並進地處理訂單。"}]', 'prepositional phrase'),
('leverage existing assets', '善用現有資產；充分利用現有資源', 'to use current resources or capabilities to gain advantage', '[{"en":"We leveraged existing assets to enter new markets quickly.","zh-TW":"我們善用現有資產快速進入新市場。"},{"en":"Leverage existing assets before investing in new ones.","zh-TW":"在投資新資產之前充分利用現有資產。"}]', 'business idiom'),
('market intelligence', '市場情報；市場資訊', 'information gathered about competitors, customers, and the market environment', '[{"en":"We invest in market intelligence to stay competitive.","zh-TW":"我們投資於市場情報以保持競爭力。"},{"en":"Market intelligence guided our pricing strategy.","zh-TW":"市場情報指導了我們的定價策略。"}]', 'business idiom'),
('net out', '淨餘；扣除後剩餘', 'to calculate the final amount after deductions', '[{"en":"Net out the fees before reporting profits.","zh-TW":"在報告利潤前扣除費用後的淨餘。"},{"en":"The gain netted out to about two million after taxes.","zh-TW":"扣除稅款後收益淨餘約兩百萬。"}]', 'phrasal verb'),
('opt in', '選擇加入；積極參與', 'to choose to participate in something', '[{"en":"Customers must opt in to receive marketing emails.","zh-TW":"客戶必須選擇加入才能接收行銷電子郵件。"},{"en":"Employees can opt in to the flexible work scheme.","zh-TW":"員工可以選擇加入彈性工作計劃。"}]', 'phrasal verb'),
('opt out', '選擇退出；放棄參與', 'to choose not to participate in something', '[{"en":"Users can opt out of data sharing at any time.","zh-TW":"用戶可以隨時選擇退出數據共享。"},{"en":"Several countries opted out of the trade deal.","zh-TW":"幾個國家選擇退出了這項貿易協議。"}]', 'phrasal verb'),
('pipe up', '開口說話；提出意見', 'to speak up and offer an opinion or suggestion', '[{"en":"Don''t hesitate to pipe up if you have a better idea.","zh-TW":"如果你有更好的想法不要猶豫，開口說出來。"},{"en":"He piped up with a valid concern during the briefing.","zh-TW":"他在簡報中提出了一個合理的問題。"}]', 'phrasal verb'),
('pitch in', '幫忙；出力；分擔', 'to contribute effort or resources to help', '[{"en":"Everyone pitched in to meet the urgent deadline.","zh-TW":"大家都幫忙以達到緊急截止日期。"},{"en":"Pitch in and help the team when it''s busy.","zh-TW":"在繁忙時出力幫助團隊。"}]', 'phrasal verb'),
('play out', '發展；展開；結果如何', 'to happen or develop in a particular way', '[{"en":"Let''s wait and see how the strategy plays out.","zh-TW":"讓我們等著看這個策略如何發展。"},{"en":"The worst-case scenario did not play out.","zh-TW":"最壞的情況沒有發展出來。"}]', 'phrasal verb'),
('plug away', '努力不懈；堅持做', 'to continue working hard at something despite difficulty', '[{"en":"The team plugged away at the issue for weeks.","zh-TW":"團隊在這個問題上努力不懈了好幾週。"},{"en":"Keep plugging away and the results will come.","zh-TW":"堅持努力，結果終將到來。"}]', 'phrasal verb'),
('reach out', '聯繫；主動接觸', 'to contact someone, especially to offer help or start a conversation', '[{"en":"Reach out to the client within 24 hours of the meeting.","zh-TW":"在會議後24小時內與客戶聯繫。"},{"en":"We reached out to potential investors at the conference.","zh-TW":"我們在會議上主動接觸了潛在投資者。"}]', 'phrasal verb'),
('ramp down', '逐步減少；縮減', 'to gradually reduce production, activity, or effort', '[{"en":"We ramped down production ahead of the retooling period.","zh-TW":"我們在改裝期前逐步減少了產量。"},{"en":"Ramp down project activities during the holiday season.","zh-TW":"在假日期間縮減專案活動。"}]', 'phrasal verb'),
('revolve around', '圍繞；以…為中心', 'to have something as the main focus or concern', '[{"en":"Our strategy revolves around customer satisfaction.","zh-TW":"我們的策略以客戶滿意度為中心。"},{"en":"The discussion revolved around budget allocation.","zh-TW":"討論圍繞預算分配展開。"}]', 'phrasal verb'),
('scale back', '縮減規模；削減', 'to reduce the size or scope of something', '[{"en":"We scaled back the project scope due to budget cuts.","zh-TW":"由於預算削減，我們縮減了專案範圍。"},{"en":"Scaling back expansion plans shows fiscal discipline.","zh-TW":"縮減擴張計劃顯示了財務紀律。"}]', 'phrasal verb');